using System.Text.Json.Serialization;

namespace MyApp.Evals.Tests;

public sealed class EvalScenario
{
    [JsonPropertyName("id")]
    public string Id { get; set; } = string.Empty;

    [JsonPropertyName("user_message")]
    public string UserMessage { get; set; } = string.Empty;

    [JsonPropertyName("expected_traits")]
    public List<string> ExpectedTraits { get; set; } = [];
}

using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public class QualityEvalTests : IAsyncLifetime
{
    private const string GoldenPath = "Quality/golden.json";
    private const string RubricPath = "Quality/rubric.md";

    private List<EvalScenario> _scenarios = [];
    private string _rubric = string.Empty;

    public async Task InitializeAsync()
    {
        var json = await File.ReadAllTextAsync(GoldenPath);
        _scenarios = JsonSerializer.Deserialize<List<EvalScenario>>(json) ?? [];
        _rubric = await File.ReadAllTextAsync(RubricPath);
    }

    public Task DisposeAsync() => Task.CompletedTask;

    [Fact]
    public void Golden_scenarios_loaded()
    {
        Assert.NotEmpty(_scenarios);
    }

    [Fact]
    public void Rubric_loaded()
    {
        Assert.False(string.IsNullOrWhiteSpace(_rubric));
    }

    [Fact]
    public void Each_scenario_has_id_and_message()
    {
        foreach (var scenario in _scenarios)
        {
            Assert.False(string.IsNullOrWhiteSpace(scenario.Id), "Scenario missing id");
            Assert.False(string.IsNullOrWhiteSpace(scenario.UserMessage), "Scenario missing user_message");
        }
    }

    [Fact]
    public void Each_scenario_has_expected_traits()
    {
        foreach (var scenario in _scenarios)
        {
            Assert.NotEmpty(scenario.ExpectedTraits);
        }
    }
}

using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals.Tests;

/// <summary>
/// Orchestrates running evaluation scenarios against the agentic app
/// and collecting quality metrics.
/// </summary>
public static class AgentEvalRunner
{
    private const string GoldenPath = "Quality/golden.json";
    private const string RubricPath = "Quality/rubric.md";

    public static async Task<List<EvalScenario>> LoadScenariosAsync()
    {
        var json = await File.ReadAllTextAsync(GoldenPath);
        return JsonSerializer.Deserialize<List<EvalScenario>>(json) ?? [];
    }

    public static async Task<string> LoadRubricAsync()
    {
        return await File.ReadAllTextAsync(RubricPath);
    }

    /// <summary>
    /// Runs a single scenario against the provided chat client and returns the conversation.
    /// </summary>
    public static async Task<List<ChatMessage>> RunScenarioAsync(
        IChatClient chatClient,
        EvalScenario scenario)
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, scenario.UserMessage)
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(new ChatMessage(ChatRole.Assistant, response.Text));
        return messages;
    }
}

